// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(c) && target != address(this));
        amount = bound(amount, 1, address(c).balance == 0 ? type(uint128).max : type(uint128).max);
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        vm.prank(c.owner());
        c.sendMoney(target, amount);
        assertTrue(address(c).balance == before - amount);
    }
}
